 static final AtomicInteger checks=new AtomicInteger();static int tests;static void check(boolean c,String why){checks.incrementAndGet();if(!c)throw new AssertionError(why);}interface Work{void run()throws Exception;}static void reject(Work w)throws Exception{try{w.run();}catch(Exception expected){checks.incrementAndGet();return;}throw new AssertionError("Expected rejection");}
 static final String GROUP="a".repeat(32),SESSION="b".repeat(32);static final InetAddress LOOP;static{try{LOOP=InetAddress.getByName("127.0.0.1");}catch(Exception e){throw new RuntimeException(e);}}
