 static void policy()throws Exception{tests++;AtomicLong now=new AtomicLong(1000);AtomicBoolean consent=new AtomicBoolean(true);InternetSharingPolicy.Run run=new InternetSharingPolicy.Run(SESSION,1,1000,InternetSharingPolicy.MIN_MS,InternetSharingPolicy.MIN_BYTES,now::get,consent::get);check(run.live(),"explicit run live");check(run.charge((int)InternetSharingPolicy.MIN_BYTES-1),"quota reserved");check(run.charge(1)&&!run.live()&&!run.charge(1),"quota finalbyte nooverflow");InternetSharingPolicy.Run next=new InternetSharingPolicy.Run(SESSION,2,1000,InternetSharingPolicy.MIN_MS,InternetSharingPolicy.MIN_BYTES,now::get,consent::get);run.stop();check(next.live(),"old Stop not new object");consent.set(false);check(!next.live()&&!next.charge(1),"membership guard");consent.set(true);next.stop();check(!next.live(),"Stop irreversible");InternetSharingPolicy.Run expiry=new InternetSharingPolicy.Run(SESSION,3,1000,InternetSharingPolicy.MIN_MS,InternetSharingPolicy.MIN_BYTES,now::get,()->true);now.set(1000+InternetSharingPolicy.MIN_MS);check(!expiry.live(),"hard elapsed expiry");for(String blocked:new String[]{"0.0.0.0","10.77.0.10","10.0.0.1","127.0.0.1","192.168.1.1","172.16.0.1","169.254.169.254","100.64.0.1","198.18.0.1","224.0.0.1","255.255.255.255"})check(!InternetSharingPolicy.publicAddress(InetAddress.getByName(blocked)),"public destination only "+blocked);check(InternetSharingPolicy.publicAddress(InetAddress.getByName("1.1.1.1")),"publicdns allowed");}
 static final class TimeoutInput extends InputStream{final byte[] bytes;int at,timeout;boolean fired;TimeoutInput(byte[] b,int t){bytes=b;timeout=t;}public int read()throws IOException{if(at==timeout&&!fired){fired=true;throw new SocketTimeoutException();}return at==bytes.length?-1:bytes[at++]&255;}public int read(byte[] b,int o,int n)throws IOException{if(at==timeout&&!fired){fired=true;throw new SocketTimeoutException();}if(at==bytes.length)return-1;int take=Math.min(n,bytes.length-at);if(!fired&&at<timeout)take=Math.min(take,timeout-at);System.arraycopy(bytes,at,b,o,take);at+=take;return take;}}
 static void frames()throws Exception{tests++;ByteArrayOutputStream h=new ByteArrayOutputStream();InternetWire.header(new DataOutputStream(h),GROUP,7,SESSION,InternetWire.TCP,address(443));DataInputStream input=new DataInputStream(new ByteArrayInputStream(h.toByteArray()));check(InternetWire.acceptHeader(input,GROUP,7,SESSION)==1,"scope header");check(InternetWire.readAddress(input).port==443,"target port");reject(()->InternetWire.acceptHeader(new DataInputStream(new ByteArrayInputStream(h.toByteArray())),GROUP,8,SESSION));byte[] payload=new byte[1400];new Random(1).nextBytes(payload);ByteArrayOutputStream output=new ByteArrayOutputStream();InternetWire.datagram(new DataOutputStream(output),address(53),payload,payload.length);for(int timeout:new int[]{1,3,4,20,output.size()-1}){InternetWire.DatagramReader reader=new InternetWire.DatagramReader();DataInputStream source=new DataInputStream(new TimeoutInput(output.toByteArray(),timeout));try{reader.read(source);}catch(SocketTimeoutException expected){}InternetWire.Datagram got=reader.read(source);check(got.address.port==53&&Arrays.equals(got.payload,payload),"partialUDPframe retained "+timeout);}ByteArrayOutputStream stream=new ByteArrayOutputStream();DataOutputStream data=new DataOutputStream(stream);data.writeInt(3);data.write(new byte[]{1,2,3});data.writeInt(0);InternetWire.StreamReader tcp=new InternetWire.StreamReader();DataInputStream partial=new DataInputStream(new TimeoutInput(stream.toByteArray(),5));try{tcp.read(partial);}catch(SocketTimeoutException expected){}check(Arrays.equals(tcp.read(partial),new byte[]{1,2,3}),"partial TCPframe retained");check(tcp.read(partial).length==0,"explicitFIN");reject(()->new InternetWire.StreamReader().read(new DataInputStream(new ByteArrayInputStream(ByteBuffer.allocate(4).putInt(4097).array()))));}
 static void socksHandshake(Socket client,int command,int port)throws Exception{DataInputStream in=new DataInputStream(client.getInputStream());DataOutputStream out=new DataOutputStream(client.getOutputStream());out.write(new byte[]{5,1,2});out.flush();check(in.readUnsignedByte()==5&&in.readUnsignedByte()==2,"SOCKS requiresauth");out.writeByte(1);out.writeByte(4);out.writeBytes("user");out.writeByte(8);out.writeBytes("password");out.flush();check(in.readUnsignedByte()==1&&in.readUnsignedByte()==0,"SOCKSauth okay");out.write(new byte[]{5,(byte)command,0});InternetWire.writeAddress(out,address(port));out.flush();check(in.readUnsignedByte()==5&&in.readUnsignedByte()==0&&in.readUnsignedByte()==0,"SOCKSready");InternetWire.Address bound=InternetWire.readAddress(in);if(command==3)udpPort=bound.port;}
 static int udpPort;
 static void transport(String own,String peer,boolean udpMode)throws Exception{tests++;HostIdentity donor=new HostIdentity(own),consumer=new HostIdentity(peer);SSLContext serverContext=donor.context(pin->pin.equals(HostIdentity.fingerprint(consumer.certificate)));SSLContext clientContext=consumer.context(pin->pin.equals(HostIdentity.fingerprint(donor.certificate)));SSLServerSocket server=(SSLServerSocket)serverContext.getServerSocketFactory().createServerSocket(0,8,LOOP);server.setNeedClientAuth(true);ServerSocket local=new ServerSocket(0,8,LOOP);ServerSocket echo=new ServerSocket(0,8,LOOP);DatagramSocket echoUdp=new DatagramSocket(new InetSocketAddress(LOOP,0));AtomicBoolean alive=new AtomicBoolean(true);AtomicInteger accounted=new AtomicInteger();AtomicReference<Throwable> error=new AtomicReference<>();InternetTunnel.Resources resources=new InternetTunnel.Resources();byte[] request="request-body-with-half-close".getBytes(),answer="returned-body-after-half-close".getBytes();CountDownLatch completed=new CountDownLatch(2);
  InternetTunnel.thread("host-echo",()->{try{if(udpMode){byte[] buffer=new byte[4096];DatagramPacket p=new DatagramPacket(buffer,buffer.length);echoUdp.receive(p);echoUdp.send(new DatagramPacket(p.getData(),p.getLength(),p.getSocketAddress()));}else try(Socket c=echo.accept()){check(Arrays.equals(c.getInputStream().readAllBytes(),request),"TCPhalfclose request");c.getOutputStream().write(answer);c.getOutputStream().flush();}}catch(Throwable failed){error.set(failed);}});
  InternetTunnel.Access donorAccess=new InternetTunnel.Access(){public boolean live(){return alive.get();}public boolean charge(int n){accounted.addAndGet(n);return alive.get();}public Socket internet(InternetWire.Address a)throws Exception{return new Socket(LOOP,echo.getLocalPort());}public DatagramSocket datagram()throws Exception{return new DatagramSocket(new InetSocketAddress(LOOP,0));}public InetAddress resolve(InternetWire.Address a){return LOOP;}public Socket upstream(int k,InternetWire.Address a)throws Exception{throw new IOException();}};
  InternetTunnel.thread("host-donor",()->{try(SSLSocket secure=(SSLSocket)server.accept()){secure.setSoTimeout(3000);secure.startHandshake();int kind=InternetWire.acceptHeader(new DataInputStream(secure.getInputStream()),GROUP,7,SESSION);InternetTunnel.donor(secure,kind,donorAccess,resources);}catch(Throwable failed){if(alive.get())error.set(failed);}finally{completed.countDown();}});
  InternetTunnel.Access clientAccess=new InternetTunnel.Access(){public boolean live(){return alive.get();}public boolean charge(int n){return alive.get();}public Socket internet(InternetWire.Address a)throws Exception{throw new IOException();}public DatagramSocket datagram()throws Exception{throw new IOException();}public InetAddress resolve(InternetWire.Address a)throws Exception{throw new IOException();}public Socket upstream(int kind,InternetWire.Address a)throws Exception{SSLSocket s=(SSLSocket)clientContext.getSocketFactory().createSocket(LOOP,server.getLocalPort());s.setSoTimeout(3000);s.startHandshake();InternetWire.header(new DataOutputStream(s.getOutputStream()),GROUP,7,SESSION,kind,a);check(s.getInputStream().read()==0,"donorACK");return s;}};
  InternetTunnel.thread("host-local-socks",()->{try(Socket accepted=local.accept()){InternetTunnel.socks(accepted,"user","password",clientAccess,resources);}catch(Throwable failed){if(alive.get())error.set(failed);}finally{completed.countDown();}});
  try(Socket client=new Socket(LOOP,local.getLocalPort())){client.setSoTimeout(5000);socksHandshake(client,udpMode?3:1,udpMode?0:echo.getLocalPort());if(udpMode){try(DatagramSocket datagram=new DatagramSocket(new InetSocketAddress(LOOP,0))){datagram.setSoTimeout(5000);ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.write(new byte[]{0,0,0});InternetWire.writeAddress(out,address(echoUdp.getLocalPort()));out.write(request);byte[] encoded=b.toByteArray();datagram.send(new DatagramPacket(encoded,encoded.length,LOOP,udpPort));DatagramPacket received=new DatagramPacket(new byte[4096],4096);datagram.receive(received);DataInputStream body=new DataInputStream(new ByteArrayInputStream(received.getData(),0,received.getLength()));check(body.readUnsignedShort()==0&&body.readUnsignedByte()==0,"UDPheader");InternetWire.readAddress(body);check(Arrays.equals(body.readAllBytes(),request),"UDPecho through authenticated TLS");}}else{client.getOutputStream().write(request);client.getOutputStream().flush();client.shutdownOutput();check(Arrays.equals(client.getInputStream().readAllBytes(),answer),"TCPfullreturn afterhalfclose");}check(accounted.get()>0,"donor payloadquota used");}
  finally{alive.set(false);resources.close();server.close();local.close();echo.close();echoUdp.close();completed.await(3,TimeUnit.SECONDS);}if(error.get()!=null)throw new AssertionError(error.get());
 }
 static void tlsReject(String own,String peer,String stranger)throws Exception{tests++;HostIdentity donor=new HostIdentity(own),consumer=new HostIdentity(peer),wrong=new HostIdentity(stranger);SSLServerSocket server=(SSLServerSocket)donor.context(pin->pin.equals(HostIdentity.fingerprint(consumer.certificate))).getServerSocketFactory().createServerSocket(0,2,LOOP);server.setNeedClientAuth(true);CountDownLatch done=new CountDownLatch(1);AtomicBoolean rejected=new AtomicBoolean();InternetTunnel.thread("host-reject",()->{try(SSLSocket s=(SSLSocket)server.accept()){s.startHandshake();}catch(Exception expected){rejected.set(true);}finally{done.countDown();}});try(SSLSocket bad=(SSLSocket)wrong.context(pin->pin.equals(HostIdentity.fingerprint(donor.certificate))).getSocketFactory().createSocket(LOOP,server.getLocalPort())){bad.setSoTimeout(3000);try{bad.startHandshake();bad.getOutputStream().write(1);bad.getInputStream().read();}catch(Exception expected){}}check(done.await(4,TimeUnit.SECONDS)&&rejected.get(),"exact production mTLS context rejects unapproved certificate");server.close();}
 static void resourcesAndStop()throws Exception{tests++;InternetTunnel.Resources old=new InternetTunnel.Resources(),replacement=new InternetTunnel.Resources();Socket first=old.own(new Socket()),next=replacement.own(new Socket());old.close();check(first.isClosed()&&!next.isClosed(),"old resource Stop preserves replacement");Socket late=new Socket();reject(()->old.own(late));check(late.isClosed(),"late resource cannot join retired owner");replacement.close();check(next.isClosed(),"replacement closes exact own socket");}
 static void localAuthReject()throws Exception{tests++;ServerSocket local=new ServerSocket(0,2,LOOP);InternetTunnel.Resources owner=new InternetTunnel.Resources();AtomicInteger opened=new AtomicInteger();AtomicBoolean live=new AtomicBoolean(true);InternetTunnel.Access access=new InternetTunnel.Access(){public boolean live(){return live.get();}public boolean charge(int n){return true;}public Socket internet(InternetWire.Address a)throws Exception{throw new IOException();}public DatagramSocket datagram()throws Exception{throw new IOException();}public InetAddress resolve(InternetWire.Address a)throws Exception{throw new IOException();}public Socket upstream(int k,InternetWire.Address a)throws Exception{opened.incrementAndGet();throw new IOException();}};CountDownLatch done=new CountDownLatch(1);InternetTunnel.thread("host-auth-reject",()->{try(Socket accepted=local.accept()){InternetTunnel.socks(accepted,"user","password",access,owner);}catch(Exception expected){}finally{done.countDown();}});try(Socket c=new Socket(LOOP,local.getLocalPort())){c.setSoTimeout(2000);DataInputStream in=new DataInputStream(c.getInputStream());DataOutputStream out=new DataOutputStream(c.getOutputStream());out.write(new byte[]{5,1,2});out.flush();in.readUnsignedShort();out.write(new byte[]{1,4});out.writeBytes("user");out.writeByte(3);out.writeBytes("bad");out.flush();check(in.readUnsignedByte()==1&&in.readUnsignedByte()!=0,"wrong local secret rejected");}check(done.await(2,TimeUnit.SECONDS)&&opened.get()==0,"untrusted local apps never open donor flow");owner.close();local.close();}
 static void pacedStop()throws Exception{tests++;AtomicBoolean live=new AtomicBoolean(true);long start=System.nanoTime();InternetRate rate=new InternetRate(()->System.nanoTime()/1000000L,()->true);check(rate.claim(8192,live::get),"initial bounded bulk slot");CountDownLatch waiting=new CountDownLatch(1);AtomicBoolean granted=new AtomicBoolean(true);Thread t=InternetTunnel.thread("host-rate-stop",()->{waiting.countDown();granted.set(rate.claim(1,live::get));});waiting.await();Thread.sleep(60);live.set(false);t.join(500);check(!t.isAlive()&&!granted.get(),"Stop cancels queued pacing permission promptly");check(System.nanoTime()-start<1000000000L,"did not wait for obsolete slot");}
